export class GpuRegistry {
  #device;
  #records = new Map();

  constructor(device) {
    if (!device?.createBuffer || !device?.createTexture) throw new TypeError('GpuRegistry requires a GPUDevice');
    this.#device = device;
  }

  createBuffer(descriptor) {
    requireLabel(descriptor?.label, 'buffer');
    const resource = this.#device.createBuffer(descriptor);
    this.#records.set(resource, Object.freeze({
      kind: 'buffer',
      label: descriptor.label,
      bytes: descriptor.size,
      details: { size: descriptor.size, usage: descriptor.usage },
    }));
    return resource;
  }

  createTexture(descriptor) {
    requireLabel(descriptor?.label, 'texture');
    const resource = this.#device.createTexture(descriptor);
    const extent = normalizeExtent(descriptor.size);
    this.#records.set(resource, Object.freeze({
      kind: 'texture',
      label: descriptor.label,
      bytes: calculateTextureBytes(descriptor),
      details: {
        size: extent,
        format: descriptor.format,
        mipLevelCount: descriptor.mipLevelCount || 1,
        sampleCount: descriptor.sampleCount || 1,
      },
    }));
    return resource;
  }

  destroy(resource) {
    const known = this.#records.delete(resource);
    if (known) resource.destroy();
    return known;
  }

  totalBytes() {
    let total = 0;
    for (const record of this.#records.values()) total += record.bytes;
    return total;
  }

  dump() {
    return [...this.#records.values()]
      .map((record) => ({ ...record, details: { ...record.details } }))
      .sort((a, b) => b.bytes - a.bytes || a.label.localeCompare(b.label));
  }
}

export function calculateTextureBytes(descriptor) {
  const bytesPerTexel = BYTES_PER_TEXEL[descriptor.format];
  if (!bytesPerTexel) throw new Error(`Byte accounting is undefined for texture format ${descriptor.format}`);
  const { width, height, depthOrArrayLayers } = normalizeExtent(descriptor.size);
  const mipLevelCount = descriptor.mipLevelCount || 1;
  const sampleCount = descriptor.sampleCount || 1;
  const shrinksInDepth = descriptor.dimension === '3d';
  let texelCount = 0;
  for (let level = 0; level < mipLevelCount; level += 1) {
    texelCount += Math.max(1, width >> level)
      * Math.max(1, height >> level)
      * (shrinksInDepth ? Math.max(1, depthOrArrayLayers >> level) : depthOrArrayLayers);
  }
  return texelCount * bytesPerTexel * sampleCount;
}

function normalizeExtent(size) {
  if (typeof size === 'number') return { width: size, height: 1, depthOrArrayLayers: 1 };
  if (Array.isArray(size)) {
    return { width: size[0], height: size[1] || 1, depthOrArrayLayers: size[2] || 1 };
  }
  return {
    width: size.width,
    height: size.height || 1,
    depthOrArrayLayers: size.depthOrArrayLayers || 1,
  };
}

function requireLabel(label, kind) {
  if (typeof label !== 'string' || label.trim() === '') throw new Error(`Every GPU ${kind} requires a label`);
}
const PROBE_FEATURES = Object.freeze([
  'shader-f16',
  'float32-filterable',
  'texture-formats-tier1',
]);

/**
 * Acquires an adapter and device without turning expected capability gaps into thrown errors.
 * Callers render the returned report; only programmer errors passed into hooks may escape.
 */
export async function acquireDevice({
  gpu = globalThis.navigator?.gpu,
  powerPreference = 'high-performance',
  forceFallbackAdapter = false,
  requiredFeatures = [],
  optionalFeatures = PROBE_FEATURES,
  requiredLimits,
  onDeviceLost,
} = {}) {
  const report = {
    ok: false,
    stage: 'availability',
    message: '',
    adapter: null,
    device: null,
    adapterInfo: {},
    adapterFeatures: [],
    enabledFeatures: [],
    missingRequiredFeatures: [],
  };

  if (!gpu) {
    report.message = 'WebGPU is not exposed by this browser.';
    return report;
  }

  try {
    report.stage = 'adapter';
    report.adapter = await gpu.requestAdapter({ powerPreference, forceFallbackAdapter });
    if (!report.adapter) {
      report.message = 'No WebGPU adapter matched the request.';
      return report;
    }

    report.adapterInfo = await readAdapterInfo(report.adapter);
    report.adapterFeatures = [...report.adapter.features].sort();
    report.missingRequiredFeatures = requiredFeatures.filter((feature) => !report.adapter.features.has(feature));
    if (report.missingRequiredFeatures.length > 0) {
      report.message = `Required WebGPU features are unavailable: ${report.missingRequiredFeatures.join(', ')}`;
      report.stage = 'feature-negotiation';
      return report;
    }

    report.enabledFeatures = [...new Set([...requiredFeatures, ...optionalFeatures])]
      .filter((feature) => report.adapter.features.has(feature));
    report.stage = 'device';
    report.device = await report.adapter.requestDevice({
      requiredFeatures: report.enabledFeatures,
      ...(requiredLimits ? { requiredLimits } : {}),
    });
    report.device.lost.then((lostInfo) => {
      onDeviceLost?.({ reason: lostInfo.reason, message: lostInfo.message });
    });
    report.ok = true;
    report.stage = 'ready';
    report.message = 'WebGPU device acquired.';
    return report;
  } catch (error) {
    report.message = error instanceof Error ? error.message : String(error);
    report.errorName = error?.name || 'Error';
    return report;
  }
}

export async function readAdapterInfo(adapter) {
  let info = adapter.info;
  if (!info && typeof adapter.requestAdapterInfo === 'function') info = await adapter.requestAdapterInfo();
  if (!info) return {};
  const names = new Set([
    ...Object.keys(info),
    'vendor', 'architecture', 'device', 'description', 'isFallbackAdapter', 'subgroupMinSize', 'subgroupMaxSize',
  ]);
  return Object.fromEntries([...names]
    .filter((name) => info[name] !== undefined)
    .map((name) => [name, info[name]]));
}

/**
 * A development-only validation scope. It always balances push/pop, even when operation throws.
 */
export async function withGpuErrorScope(device, label, operation, {
  enabled = true,
  filter = 'validation',
  onError,
} = {}) {
  if (!enabled) return { value: await operation(), error: null };
  device.pushErrorScope(filter);
  let value;
  let thrown;
  try {
    value = await operation();
  } catch (error) {
    thrown = error;
  }
  const error = await device.popErrorScope();
  if (error) onError?.({ label, filter, message: error.message });
  if (thrown) throw thrown;
  return { value, error };
}

