import { fetchWgsl } from '../gpu/wgsl.js';

export async function createField2dRenderer({ device, canvas, sim, dev = true, onCompilationMessage }) {
  const context = canvas.getContext('webgpu');
  const format = navigator.gpu.getPreferredCanvasFormat();
  context.configure({
    device,
    format,
    alphaMode: 'opaque',
    usage: GPUTextureUsage.RENDER_ATTACHMENT | GPUTextureUsage.COPY_SRC,
  });
  const fieldLayout = device.createBindGroupLayout({
    label: 'field2d-field-layout',
    entries: [{
      binding: 0,
      visibility: GPUShaderStage.FRAGMENT,
      texture: { sampleType: 'unfilterable-float', viewDimension: '2d' },
    }],
  });
  const agentLayout = device.createBindGroupLayout({
    label: 'field2d-agent-layout',
    entries: [{
      binding: 0,
      visibility: GPUShaderStage.VERTEX,
      buffer: { type: 'read-only-storage' },
    }],
  });
  const emptyLayout = device.createBindGroupLayout({ label: 'field2d-empty-layout', entries: [] });
  const source = await fetchWgsl(new URL('./field2d.wgsl', import.meta.url));
  const module = device.createShaderModule({ label: 'field2d-module', code: source });
  if (dev && typeof module.getCompilationInfo === 'function') {
    const info = await module.getCompilationInfo();
    for (const message of info.messages) onCompilationMessage?.({ shader: 'field2d', ...message });
    const errors = info.messages.filter(({ type }) => type === 'error');
    if (errors.length > 0) throw new Error(errors.map(({ message }) => message).join('; '));
  }
  const fieldPipeline = await device.createRenderPipelineAsync({
    label: 'field2d-field-pipeline',
    layout: device.createPipelineLayout({
      label: 'field2d-field-pipeline-layout',
      bindGroupLayouts: [fieldLayout, emptyLayout],
    }),
    vertex: { module, entryPoint: 'fieldVertex' },
    fragment: { module, entryPoint: 'fieldFragment', targets: [{ format }] },
    primitive: { topology: 'triangle-list' },
  });
  const agentPipeline = await device.createRenderPipelineAsync({
    label: 'field2d-agent-pipeline',
    layout: device.createPipelineLayout({
      label: 'field2d-agent-pipeline-layout',
      bindGroupLayouts: [emptyLayout, agentLayout],
    }),
    vertex: { module, entryPoint: 'agentVertex' },
    fragment: {
      module,
      entryPoint: 'agentFragment',
      targets: [{
        format,
        blend: {
          color: { srcFactor: 'src-alpha', dstFactor: 'one-minus-src-alpha', operation: 'add' },
          alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha', operation: 'add' },
        },
      }],
    },
    primitive: { topology: 'point-list' },
  });
  const fieldBind = device.createBindGroup({
    label: 'field2d-field-bind',
    layout: fieldLayout,
    entries: [{ binding: 0, resource: sim.currentFieldView() }],
  });
  const emptyBind = device.createBindGroup({ label: 'field2d-empty-bind', layout: emptyLayout, entries: [] });
  const agentBuffers = sim.allAgentBuffers();
  const agentBinds = new Map(agentBuffers.map((buffer, index) => [buffer, device.createBindGroup({
    label: `field2d-agent-bind-${index}`,
    layout: agentLayout,
    entries: [{ binding: 0, resource: { buffer } }],
  })]));

  return {
    render({ showAgentDots = true } = {}) {
      resizeCanvas(canvas);
      const encoder = device.createCommandEncoder({ label: 'field2d-render-encoder' });
      const pass = encoder.beginRenderPass({
        label: 'field2d-render-pass',
        colorAttachments: [{
          view: context.getCurrentTexture().createView(),
          clearValue: { r: 0.004, g: 0.006, b: 0.005, a: 1 },
          loadOp: 'clear',
          storeOp: 'store',
        }],
      });
      pass.setPipeline(fieldPipeline);
      pass.setBindGroup(0, fieldBind);
      pass.setBindGroup(1, emptyBind);
      pass.draw(3);
      if (showAgentDots) {
        pass.setPipeline(agentPipeline);
        pass.setBindGroup(0, emptyBind);
        pass.setBindGroup(1, agentBinds.get(sim.currentAgentBuffer()));
        pass.drawIndirect(sim.renderIndirectBuffer, 0);
      }
      pass.end();
      device.queue.submit([encoder.finish()]);
    },
  };
}

function resizeCanvas(canvas) {
  const width = Math.max(1, Math.round(canvas.clientWidth * devicePixelRatio));
  const height = Math.max(1, Math.round(canvas.clientHeight * devicePixelRatio));
  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width;
    canvas.height = height;
  }
}
// Flat-field development renderer.
// Inputs: nearest-loaded canonical r32float food field; optional 32 B Agent records.
// Output: canvas colour plus one-pixel agent-dot overlay.
// Invariants: no sampler or atlas logic; drawIndirect limits dots to live agents.
// Anchors: M3 dev.html growth and webgpu/render2d.js technique reference.

struct Agent {
  uvPos: vec2<f32>,
  heading: f32,
  reserve: f32,
  idLo: u32,
  idHi: u32,
  flags: u32,
  padding: u32,
}

struct FieldVertex { @builtin(position) position: vec4<f32>, @location(0) uv: vec2<f32> }

@group(0) @binding(0) var foodField: texture_2d<f32>;
@group(1) @binding(0) var<storage, read> agents: array<Agent>;

@vertex
fn fieldVertex(@builtin(vertex_index) index: u32) -> FieldVertex {
  let uv = vec2<f32>(f32((index << 1u) & 2u), f32(index & 2u));
  var output: FieldVertex;
  output.position = vec4<f32>(uv * 2.0 - vec2<f32>(1.0), 0.0, 1.0);
  output.uv = vec2<f32>(uv.x, 1.0 - uv.y);
  return output;
}

@fragment
fn fieldFragment(input: FieldVertex) -> @location(0) vec4<f32> {
  let size = textureDimensions(foodField);
  let texelPos = clamp(vec2<i32>(input.uv * vec2<f32>(size)), vec2<i32>(0), vec2<i32>(size) - vec2<i32>(1));
  let food = max(textureLoad(foodField, texelPos, 0).r, 0.0);
  let signal = pow(clamp(food * 2.0, 0.0, 1.0), 0.55);
  let deep = vec3<f32>(0.004, 0.012, 0.014);
  let middle = vec3<f32>(0.02, 0.35, 0.28);
  let bright = vec3<f32>(0.80, 1.0, 0.88);
  let colour = select(mix(deep, middle, signal * 2.0), mix(middle, bright, signal * 2.0 - 1.0), signal > 0.5);
  return vec4<f32>(colour, 1.0);
}

@vertex
fn agentVertex(@builtin(vertex_index) index: u32) -> @builtin(position) vec4<f32> {
  let uvPos = agents[index].uvPos;
  return vec4<f32>(uvPos.x * 2.0 - 1.0, 1.0 - uvPos.y * 2.0, 0.0, 1.0);
}

@fragment
fn agentFragment() -> @location(0) vec4<f32> {
  return vec4<f32>(0.75, 1.0, 0.84, 0.72);
}

# Generated assets

Versioned outputs from the v2 asset tools are committed here once their formats freeze.

## Gold-wafer lookup

Run `npm run bake:goldlut` from `v2/` to regenerate the renderer lookup. The command prints the
full SHA-256 values needed by a future asset manifest; the first eight digits of the compressed
file hash are part of its name.

- File: `gold-lut.d489076d.bin.gz`
- Compressed SHA-256: `d489076d3715a8c0ddbad4e62887ee31c40dd4738f2e116dd3c8e3a47bc6a23b`
- Inflated SHA-256: `c77d3872956c1735733709acc620e9ea26822030575022e8f6f5edfdcae24bd7`
- Pixel payload SHA-256: `0ec04b7d6ed55209f26512ebf8270d9035291eab75c114c53979d2634f0f6f94`
- Inflated layout: 96-byte `GLUT` v1 header followed by 600×256×RGBA8 pixels

The header carries the coordinate mapping and pixel hash. Independent header and payload CRC32
values make accidental corruption fail before the renderer uploads the texture.
